import '../../benchmark/value_store/tool_support.dart';

Future<void> main() async {
  const root = 'build/scoped-cleanup-investigation';
  const out = '$root/final-timing';
  const sources = {
    'combined': '$root/headless-baseline',
    'scoped_collections_recent': '$root/final-build',
  };
  if (Directory(out).existsSync()) throw StateError('Output exists');
  final builds = {for (final entry in sources.entries)
    entry.key: readJson('${entry.value}/manifest.json')};
  final reference = builds['combined']!;
  for (final entry in (reference['variant_sha256']['combined'] as Map).entries) {
    if (hashFile('$root/start/${entry.key}') != entry.value) {
      throw StateError('Starting library differs from saved baseline: ${entry.key}');
    }
  }
  for (final entry in sources.entries) {
    final variant = entry.key;
    final build = entry.value;
    if (builds[variant]!['headless'] != true) throw StateError('Refusing windowed host');
    if (builds[variant]!['flutter']['frameworkRevision'] != reference['flutter']['frameworkRevision']) {
      throw StateError('Flutter versions differ');
    }
    final receipts = jsonDecode(File('$build/receipts.json').readAsStringSync()) as List;
    for (final step in ['validation', 'jit-build', 'aot-build']) {
      if (!receipts.any((r) => r['job'] == '$variant-$step' && r['exit_code'] == 0)) {
        throw StateError('Missing successful $variant-$step');
      }
    }
    for (final source in ['native_main.dart', 'profile_support.dart',
      'workloads/dependency.dart', 'workloads/dependency_shapes.dart', 'workloads/sparse_writes.dart']) {
      if (hashFile('$build/packages/$variant/benchmark/value_store/$source') !=
          hashFile('${sources['combined']}/packages/combined/benchmark/value_store/$source')) {
        throw StateError('Workload changed: $variant/$source');
      }
    }
  }
  final manifest = {...reference,
    'variants': sources.keys.toList(), 'passes': 3, 'trials': 9,
