    'library_source': Directory('$root/start').absolute.path,
    'variant_sha256': {for (final variant in sources.keys)
      variant: builds[variant]!['variant_sha256'][variant]},
    'artifacts': {for (final variant in sources.keys)
      for (final mode in ['jit', 'aot'])
        '$variant/$mode': builds[variant]!['artifacts']['$variant/$mode']},
    'build_manifests': {for (final entry in sources.entries)
      entry.key: '${entry.value}/manifest.json'},
    'runner_sha256': hashFile(Platform.script.toFilePath()),
  };
  Directory(out).createSync();
  writeJson('$out/manifest.json', manifest);
  final jobs = [for (final variant in sources.keys)
    for (final mode in ['jit', 'aot'])
      for (final suite in manifest['suites'] as List) (variant, mode, suite)];
  final receipts = <Object>[];
  for (var pass = 1; pass <= 3; pass++) {
    for (final (variant, mode, suite) in pass.isOdd ? jobs : jobs.reversed) {
      final artifact = (manifest['artifacts'] as Map)['$variant/$mode'];
      final binary = '${artifact['app']}/Contents/MacOS/loon_profile';
      if (hashFile(binary) != artifact['executable_sha256']) throw StateError('Binary changed');
      for (final entry in (artifact['dart_artifacts'] as Map).entries) {
        if (hashFile('${artifact['app']}/${entry.key}') != entry.value) throw StateError('Dart artifact changed');
      }
      final label = '$pass-$variant-$mode-$suite';
      final load = await commandOutput(['sysctl', '-n', 'vm.loadavg']);
      final watch = Stopwatch()..start();
      final env = {
        'PROFILE_SUITE': '$suite', 'PROFILE_VARIANT': variant,
        'PROFILE_EXPECT_MODE': mode, 'PROFILE_EXIT': 'true', 'PROFILE_CASE': '',
        'PROFILE_OUTPUT': File('$out/$label.json').absolute.path,
        'PROFILE_WARMUPS': '5', 'PROFILE_WARMUP_MS': '200', 'PROFILE_TRIALS': '9',
        'PROFILE_ORDER': pass.isOdd ? 'forward' : 'reverse',
      };
      final result = await Process.run(binary, [], environment: {...Platform.environment, ...env});
      File('$out/$label.log').writeAsStringSync('${result.stdout}${result.stderr}');
      receipts.add({'job': label, 'command': [binary], 'env': env, 'exit_code': result.exitCode,
        'seconds': watch.elapsedMilliseconds / 1000, 'load_average_before': load,
        'load_average_after': await commandOutput(['sysctl', '-n', 'vm.loadavg'])});
      writeJson('$out/receipts.json', receipts);
      if (result.exitCode != 0) throw StateError('$label failed');
      if (readJson('$out/$label.json')['headless'] != true) throw StateError('Not headless');
      stdout.writeln('$label: passed');
    }
  }
  await commandOutput([Platform.resolvedExecutable, 'run',
    'benchmark/value_store/summarize.dart', out]);
}

