import Cocoa

// A bounded, read-only focus audit around one benchmark process.
let args = CommandLine.arguments
guard args.count == 4 else { fatalError("Expected binary, mode and output prefix") }
let binary = URL(fileURLWithPath: args[1])
let contents = binary.deletingLastPathComponent().deletingLastPathComponent()
let info = NSDictionary(contentsOf: contents.appendingPathComponent("Info.plist"))!
guard info["LSBackgroundOnly"] as? Bool == true, info["NSMainNibFile"] == nil else {
  fatalError("Refusing to launch a non-headless host")
}
let process = Process()
process.executableURL = binary
var env = ProcessInfo.processInfo.environment
env.merge([
  "PROFILE_SUITE": "sparse_writes", "PROFILE_VARIANT": "combined",
  "PROFILE_EXPECT_MODE": args[2], "PROFILE_EXIT": "true",
  "PROFILE_WARMUPS": "1", "PROFILE_WARMUP_MS": "0", "PROFILE_TRIALS": "1",
  "PROFILE_OUTPUT": args[3] + ".json"
]) { _, new in new }
process.environment = env
FileManager.default.createFile(atPath: args[3] + ".log", contents: nil)
let log = FileHandle(forWritingAtPath: args[3] + ".log")!
process.standardOutput = log
process.standardError = log
var activated = false
var checkedPolicies: Set<Int> = []
let observer = NSWorkspace.shared.notificationCenter.addObserver(
  forName: NSWorkspace.didActivateApplicationNotification, object: nil, queue: nil
) { notification in
  if let app = notification.userInfo?[NSWorkspace.applicationUserInfoKey] as? NSRunningApplication,
     app.processIdentifier == process.processIdentifier {
    activated = true
  }
}
try process.run()
let deadline = Date().addingTimeInterval(60)
while process.isRunning && Date() < deadline {
  if let app = NSRunningApplication(processIdentifier: process.processIdentifier) {
    checkedPolicies.insert(app.activationPolicy.rawValue)
    if app.isActive { activated = true }
  }
  RunLoop.current.run(until: Date().addingTimeInterval(0.02))
}
if process.isRunning { process.terminate(); fatalError("Headless probe timed out") }
process.waitUntilExit()
NSWorkspace.shared.notificationCenter.removeObserver(observer)
let report: [String: Any] = [
  "exit_code": process.terminationStatus,
  "activated": activated,
  "activation_policies": checkedPolicies.sorted(),
  "expected_policy": NSApplication.ActivationPolicy.prohibited.rawValue,
  "background_only": true,
  "main_nib": false,
]
let json = try JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys])
try json.write(to: URL(fileURLWithPath: args[3] + "-focus.json"))
print(String(data: json, encoding: .utf8)!)
if process.terminationStatus != 0 || activated || checkedPolicies != [NSApplication.ActivationPolicy.prohibited.rawValue] {
  exit(1)
}
